{
  "claims": [
    {
      "claim_text": "PostgreSQL accepts all four standard isolation levels but only implements three distinct behaviors.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 states PostgreSQL requests any of the four standard levels but internally only three distinct levels are implemented.",
      "citations": [
        {"index": 0, "quote": "In PostgreSQL, you can request any of the four standard transaction isolation levels, but internally only three distinct isolation levels are implemented"}
      ]
    },
    {
      "claim_text": "Read Uncommitted is treated identically to Read Committed.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 explicitly says Read Uncommitted mode behaves like Read Committed.",
      "citations": [
        {"index": 0, "quote": "PostgreSQL's Read Uncommitted mode behaves like Read Committed"}
      ]
    },
    {
      "claim_text": "Read Committed is the default isolation level.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 2 states Read Committed is the default isolation level in PostgreSQL.",
      "citations": [
        {"index": 2, "quote": "Read Committed is the default isolation level in PostgreSQL."}
      ]
    },
    {
      "claim_text": "In Read Committed, each statement sees a snapshot of data committed before that statement began.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 2 says a SELECT sees only data committed before the query began and sees a snapshot as of the instant the query begins.",
      "citations": [
        {"index": 2, "quote": "a SELECT query (without a FOR UPDATE/SHARE clause) sees only data committed before the query began"},
        {"index": 2, "quote": "a SELECT query sees a snapshot of the database as of the instant the query begins to run"}
      ]
    },
    {
      "claim_text": "In Read Committed, two SELECTs in one transaction can observe different data if other transactions commit in between.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 2 explicitly notes two successive SELECT commands can see different data within a single transaction if other transactions commit between them.",
      "citations": [
        {"index": 2, "quote": "two successive SELECT commands can see different data, even though they are within a single transaction, if other transactions commit changes after the first SELECT starts and before the second SELECT starts"}
      ]
    },
    {
      "claim_text": "Repeatable Read takes its snapshot at the start of the first non-transaction-control statement in the transaction.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 4 states a query in a repeatable read transaction sees a snapshot as of the start of the first non-transaction-control statement.",
      "citations": [
        {"index": 4, "quote": "a query in a repeatable read transaction sees a snapshot as of the start of the first non-transaction-control statement in the transaction"}
      ]
    },
    {
      "claim_text": "In Repeatable Read, all queries in the transaction see the same stable view.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 4 says successive SELECTs see the same data, and passage 5 says Repeatable Read provides a rigorous guarantee of a completely stable view.",
      "citations": [
        {"index": 4, "quote": "successive SELECT commands within a single transaction see the same data"},
        {"index": 5, "quote": "The Repeatable Read mode provides a rigorous guarantee that each transaction sees a completely stable view of the database."}
      ]
    },
    {
      "claim_text": "Repeatable Read prevents phantom reads, exceeding the SQL standard's minimum requirements for that level.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 1 says Repeatable Read does not allow phantom reads and this is acceptable because higher guarantees are acceptable; passage 3 says it is a stronger guarantee than required.",
      "citations": [
        {"index": 1, "quote": "PostgreSQL's Repeatable Read implementation does not allow phantom reads"},
        {"index": 1, "quote": "higher guarantees are acceptable"},
        {"index": 3, "quote": "This is a stronger guarantee than is required by the SQL standard for this isolation level"}
      ]
    },
    {
      "claim_text": "Repeatable Read does not prevent serialization anomalies.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 3 says Repeatable Read prevents all phenomena in Table 13.1 except for serialization anomalies.",
      "citations": [
        {"index": 3, "quote": "prevents all of the phenomena described in Table 13.1 except for serialization anomalies"}
      ]
    },
    {
      "claim_text": "A Repeatable Read transaction may see a state that never existed in any serial execution, for example reading an updated control record but a stale detail record.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 5 gives exactly this example of a read-only Repeatable Read transaction seeing an updated control record but not a detail record.",
      "citations": [
        {"index": 5, "quote": "even a read-only transaction at this level may see a control record updated to show that a batch has been completed but not see one of the detail records which is logically part of the batch"}
      ]
    },
    {
      "claim_text": "Enforcing business rules at Repeatable Read typically requires explicit locking such as SELECT FOR UPDATE or table-level locks.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 5 says attempts to enforce business rules at this level are not likely to work without careful use of explicit locks; passage 8 mentions Read Committed or Repeatable Read may need a table lock or SELECT FOR UPDATE/SHARE.",
      "citations": [
        {"index": 5, "quote": "Attempts to enforce business rules by transactions running at this isolation level are not likely to work correctly without careful use of explicit locks to block conflicting transactions."},
        {"index": 8, "quote": "a Read Committed or Repeatable Read transaction which wants to ensure data consistency may need to take out a lock on an entire table"},
        {"index": 8, "quote": "it may use SELECT FOR UPDATE or SELECT FOR SHARE"}
      ]
    },
    {
      "claim_text": "Serializable is implemented since version 9.1.",
      "verdict": "UNSUPPORTED",
      "reasoning": "Passage 6 says prior to version 9.1 a request for Serializable provided the same behavior as Repeatable Read, but does not state that Serializable was implemented since 9.1.",
      "citations": []
    },
    {
      "claim_text": "Serializable works exactly like Repeatable Read but adds monitoring based on predicate locks that track read-write dependencies among concurrent transactions.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 7 says Serializable works exactly the same as Repeatable Read except it monitors for conditions causing serialization anomalies; passage 8 says predicate locking is used to identify and flag dependencies among concurrent Serializable transactions.",
      "citations": [
        {"index": 7, "quote": "this isolation level works exactly the same as Repeatable Read except that it also monitors for conditions which could make execution of a concurrent set of serializable transactions behave in a manner inconsistent with all possible serial (one at a time) executions"},
        {"index": 8, "quote": "To guarantee true serializability PostgreSQL uses predicate locking"},
        {"index": 8, "quote": "They are used to identify and flag dependencies among concurrent Serializable transactions"}
      ]
    },
    {
      "claim_text": "Predicate locks never block or contribute to deadlocks.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 8 states these locks do not cause any blocking and cannot play any part in causing a deadlock.",
      "citations": [
        {"index": 8, "quote": "In PostgreSQL these locks do not cause any blocking and therefore can not play any part in causing a deadlock."}
      ]
    },
    {
      "claim_text": "If a combination of Serializable transactions could produce a result inconsistent with any serial order, one of them is aborted with a serialization failure.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 7 says detection of conditions causing a serialization anomaly will trigger a serialization failure.",
      "citations": [
        {"index": 7, "quote": "detection of the conditions which could cause a serialization anomaly will trigger a serialization failure"}
      ]
    },
    {
      "claim_text": "You should use Serializable when correctness depends on invariants spanning multiple rows or predicates that are awkward to protect with explicit locks.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages describe Serializable's behavior but do not give this recommendation about when to use it.",
      "citations": []
    },
    {
      "claim_text": "Applications using Serializable should be prepared to retry transactions that fail with a serialization error (SQLSTATE 40001).",
      "verdict": "UNSUPPORTED",
      "reasoning": "Passage 7 says applications must be prepared to retry transactions due to serialization failures, but the SQLSTATE 40001 code is not mentioned in the passages.",
      "citations": []
    },
    {
      "claim_text": "Keep transactions short at Serializable because monitoring overhead and probability of conflicts and retries grow with transaction duration and concurrency.",
      "verdict": "UNSUPPORTED",
      "reasoning": "Passage 7 mentions monitoring overhead and serialization failures but does not advise keeping transactions short or state that conflict probability grows with duration and concurrency.",
      "citations": []
    },
    {
      "claim_text": "Even Serializable can report unique constraint violations if some transactions insert keys without first checking for them, so all writers should follow a consistent check-before-insert protocol.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 9 says unique constraint violations can occur even after checking, and can be avoided by making sure all Serializable transactions that insert potentially conflicting keys explicitly check first.",
      "citations": [
        {"index": 9, "quote": "it is possible to see unique constraint violations caused by conflicts with overlapping Serializable transactions even after explicitly checking that the key isn't present before attempting to insert it"},
        {"index": 9, "quote": "This can be avoided by making sure that all Serializable transactions that insert potentially conflicting keys explicitly check if they can do so first."}
      ]
    },
    {
      "claim_text": "For simple read-modify-write patterns on single rows, Read Committed combined with SELECT FOR UPDATE, or explicit advisory locks, is often simpler and faster than Serializable.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages mention SELECT FOR UPDATE and locks but do not compare simplicity or speed with Serializable for single-row read-modify-write patterns, nor mention advisory locks.",
      "citations": []
    }
  ]
}
